44	/**
45	 * Migrates a v1 save (40 slots, 10-slot hotbar) to v2 (36 slots, 9-slot
46	 * hotbar): non-empty slots are packed in order, stackable items merge into
47	 * earlier stacks, and anything that still overflows 36 slots is dropped.
48	 */
49	/** Coerces a persisted hotbar index to a finite integer within 0..HOTBAR_SLOTS-1. */
50	function normalizeSelectedSlot(value: number): number {
51	  const index = Number.isFinite(value) ? Math.floor(value) : 0;
52	  return Math.max(0, Math.min(HOTBAR_SLOTS - 1, index));
53	}
54	
55	export function migrateSaveV1toV2(save: SaveDataV1): SaveDataV2 {
56	  const migrated: SaveDataV2 = { ...save, version: 2, selectedSlot: normalizeSelectedSlot(save.selectedSlot) };
57	
58	  if (Array.isArray(save.inventorySlots)) {
59	    const packed: Array<{ id: string | null; count: number; durability?: number }> = [];
60	    for (const saved of save.inventorySlots) {
61	      if (!saved?.id || saved.count <= 0) continue;
62	      // Items without durability stack; merge them into an earlier stack first.
63	      const stackable = ITEM_DEF_BY_ID[saved.id] ? !ITEM_DEF_BY_ID[saved.id].maxDurability : false;
64	      let remaining = saved.count;
65	      if (stackable) {
66	        for (const slot of packed) {
67	          if (slot.id !== saved.id || slot.count >= MAX_STACK_SIZE) continue;
68	          const moved = Math.min(MAX_STACK_SIZE - slot.count, remaining);
69	          slot.count += moved;
70	          remaining -= moved;
71	          if (remaining === 0) break;
72	        }
73	      }
74	      while (remaining > 0 && packed.length < INVENTORY_SLOTS) {
75	        const moved = Math.min(maxStackSizeForItem(saved.id), remaining);
76	        packed.push({ id: saved.id, count: moved, durability: saved.durability });
77	        remaining -= moved;
78	      }
79	    }
80	    migrated.inventorySlots = packed;
81	  }
82	
83	  return migrated;
84	}
