165	/**
166	 * Migrates a v11 save to v12 — armor moves to dedicated storage. The legacy
167	 * `equippedArmor` was a by-id reference into `inventorySlots` (the worn item also
168	 * lived in the inventory). For each valid equip, move the matching inventory item
169	 * out into the armor record (preserving durability/enchantments/customName); drop
170	 * equips whose item isn't found or isn't valid armor for the slot. Pre-`inventorySlots`
171	 * (legacy counts-only) saves simply drop the equip map and keep items in inventory.
172	 */
173	export function migrateSaveV11toV12(save: SaveDataV11): SaveDataV12 {
174	  const legacy = save.equippedArmor;
175	  if (!legacy || !Array.isArray(save.inventorySlots)) {
176	    return { ...save, version: 12, equippedArmor: undefined };
177	  }
178	  const slots = save.inventorySlots.slice();
179	  const equipped: SavedEquippedArmor = {};
180	  for (const armorSlot of ARMOR_SLOTS) {
181	    const id = legacy[armorSlot];
182	    if (!id) continue;
183	    const def = ITEM_DEF_BY_ID[id];
184	    if (def?.kind !== "armor" || def.armorSlot !== armorSlot) continue; // drop invalid equips
185	    const idx = slots.findIndex((s) => s?.id === id && s.count > 0);
186	    if (idx < 0) continue; // item not in inventory → drop the equip
187	    equipped[armorSlot] = slots[idx]; // preserves durability/enchantments/customName
188	    slots[idx] = { id: null, count: 0 };
189	  }
190	  return { ...save, version: 12, inventorySlots: slots, equippedArmor: equipped };
191	}
