277	/**
278	 * Validates a decoded save of any historical version and migrates it to the
279	 * current SaveData. Total: unknown shapes, future versions, and migration
280	 * throws all yield null. Shared by the JSON string path (readSave) and
281	 * callers that hold the decoded object itself (the IndexedDB save store).
282	 */
283	export function parseSave(value: unknown): SaveData | null {
284	  try {
285	    const parsed = value as
286	      | SaveData
287	      | SaveDataV16
288	      | SaveDataV15
289	      | SaveDataV14
290	      | SaveDataV13
291	      | SaveDataV12
292	      | SaveDataV11
293	      | SaveDataV10
294	      | SaveDataV9
295	      | SaveDataV8
296	      | SaveDataV7
297	      | SaveDataV6
298	      | SaveDataV5
299	      | SaveDataV4
300	      | SaveDataV3
301	      | SaveDataV2
302	      | SaveDataV1;
303	    if (!parsed || !Number.isFinite(parsed.seed) || !Array.isArray(parsed.changes)) return null;
304	    let migrated:
305	      | SaveDataV2
306	      | SaveDataV3
307	      | SaveDataV4
308	      | SaveDataV5
309	      | SaveDataV6
310	      | SaveDataV7
311	      | SaveDataV8
312	      | SaveDataV9
313	      | SaveDataV10
314	      | SaveDataV11
315	      | SaveDataV12
316	      | SaveDataV13
317	      | SaveDataV14
318	      | SaveDataV15
319	      | SaveDataV16
320	      | SaveData = parsed.version === 1 ? migrateSaveV1toV2(parsed) : parsed;
321	    if (migrated.version === 2) migrated = migrateSaveV2toV3(migrated);
322	    if (migrated.version === 3) migrated = migrateSaveV3toV4(migrated);
323	    if (migrated.version === 4) migrated = migrateSaveV4toV5(migrated);
324	    if (migrated.version === 5) migrated = migrateSaveV5toV6(migrated);
325	    if (migrated.version === 6) migrated = migrateSaveV6toV7(migrated);
326	    if (migrated.version === 7) migrated = migrateSaveV7toV8(migrated);
327	    if (migrated.version === 8) migrated = migrateSaveV8toV9(migrated);
328	    if (migrated.version === 9) migrated = migrateSaveV9toV10(migrated);
329	    if (migrated.version === 10) migrated = migrateSaveV10toV11(migrated);
330	    if (migrated.version === 11) migrated = migrateSaveV11toV12(migrated);
331	    if (migrated.version === 12) migrated = migrateSaveV12toV13(migrated);
332	    if (migrated.version === 13) migrated = migrateSaveV13toV14(migrated);
333	    if (migrated.version === 14) migrated = migrateSaveV14toV15(migrated);
334	    if (migrated.version === 15) migrated = migrateSaveV15toV16(migrated);
335	    if (migrated.version === 16) migrated = migrateSaveV16toV17(migrated);
336	    if (migrated.version !== 17) return null;
337	    if (!Array.isArray(migrated.players)) return null;
338	    return migrated;
339	  } catch {
340	    return null;
341	  }
342	}
