416	/** Validates persisted enchantments: known ids and integer levels clamped to 1..(that enchant's max); undefined when none survive. */
417	function restoreEnchantments(saved: SavedSlot["enchantments"]): Enchantment[] | undefined {
418	  if (!Array.isArray(saved)) return undefined;
419	  const out: Enchantment[] = [];
420	  for (const entry of saved) {
421	    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_ENCHANT_IDS, entry.id)) continue;
422	    if (!Number.isFinite(entry.level) || Math.floor(entry.level) < 1) continue;
