570	    if (mob.owner != null) saved.owner = mob.owner;
571	    if (mob.sitting) saved.sitting = true;
572	    if (mob.ageTimer > 0) saved.ageTimer = mob.ageTimer;
573	    if (mob.profession != null) saved.profession = mob.profession;
