170	export function tickAquaticSpawnDirector(state: GameState, dt: number, rng: () => number): void {
171	  state.timers.aquaticSpawnTimer += dt;
172	  if (state.timers.aquaticSpawnTimer < AQUATIC_SPAWN_INTERVAL_SECONDS) return;
173	  state.timers.aquaticSpawnTimer = 0;
174	
175	  // Passive fish top-up. Hostiles never count against the fish budget — a full
176	  // night of drowned must not starve the cod schools.
177	  let fish = 0;
178	  for (const mob of state.mobs) if (MOB_TEMPLATES[mob.kind].aquatic && !mob.hostile) fish += 1;
179	  if (fish < AQUATIC_CAP) {
180	    const kind: MobKind = rng() < 0.6 ? "cod" : "salmon";
181	    const count = Math.min(AQUATIC_CAP - fish, 1 + (rng() > 0.6 ? 1 : 0));
182	    const center = spawnCenterPlayer(state, rng);
183	    if (!center) return;
184	    spawnAquaticGroup(state, kind, count, center.position.x, center.position.z, RENDER_RADIUS * 0.85, rng);
185	  }
186	
187	  // Night waters turn hostile (Peaceful spawns none; daylight ends it).
188	  if (!hostilesSpawn(state.difficulty) || state.daylight >= HOSTILE_SPAWN_BELOW_DAYLIGHT) return;
189	  let drowned = 0;
190	  let hostiles = 0;
191	  for (const mob of state.mobs) {
192	    if (mob.kind === "drowned") drowned += 1;
193	    if (mob.hostile) hostiles += 1;
194	  }
195	  const cap = Math.round(HOSTILE_CAP * hostileCapScale(state.difficulty)) * partyCapScale(state);
196	  if (drowned >= DROWNED_CAP || hostiles >= cap) return;
197	  const center = spawnCenterPlayer(state, rng);
198	  if (!center) return;
199	  spawnAquaticGroup(state, "drowned", 1, center.position.x, center.position.z, RENDER_RADIUS * 0.85, rng, true, DROWNED_SPAWN_MIN_RADIUS);
200	}
201	
202	/**
203	 * Seeds each village center with its resident villager population (faction
204	 * "villager", so they persist with the world). Called once when a world has no
205	 * villagers yet — a fresh world or one upgraded from a pre-village save; a reload
206	 * of a populated world restores its residents instead, so they aren't doubled.
207	 */
208	export function spawnVillageResidents(state: GameState, sites: Array<{ x: number; z: number }>, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
209	  for (const site of sites) {
210	    for (let i = 0; i < GEN.villagersPerVillage; i += 1) {
211	      const pos = randomLandPointNear(state.world, surfaceYAt, site.x, site.z, 8, rng, 0);
212	      pushMob(state, "villager", false, pos.x, pos.y, pos.z, rng);
213	    }
214	  }
215	}
216	
217	/**
218	 * Assigns a trade profession (round-robin) to every villager that doesn't have
219	 * one yet — newly seeded residents on a fresh world. Restored residents keep
220	 * their saved profession, so this skips them (they're not professionless).
221	 */
222	export function assignVillagerProfessions(state: GameState): void {
223	  let next = 0;
224	  for (const mob of state.mobs) {
225	    if (mob.faction !== "villager" || mob.profession != null) continue;
226	    mob.profession = PROFESSIONS[next % PROFESSIONS.length];
227	    next += 1;
228	  }
229	}
230	
231	/**
232	 * The player a spawn wave centers on. One player: that player, with no rng
233	 * consumed — the single-player stream stays byte-identical to the old code.
234	 * Several players: a uniformly random one per wave, so spawns spread across
235	 * the party instead of piling onto whoever is primary. None: null (idle room).
236	 */
237	function spawnCenterPlayer(state: GameState, rng: () => number): PlayerState | null {
238	  if (state.players.size === 0) return null;
239	  if (state.players.size === 1) return state.players.values().next().value ?? null;
240	  const all = [...state.players.values()];
241	  return all[Math.min(all.length - 1, Math.floor(rng() * all.length))];
242	}
243	
244	/**
245	 * Scales a global mob cap with the party size: 1–2 players keep the SP cap,
246	 * and each further pair adds another cap's worth — so 8 players don't starve
247	 * for mobs, but also don't each drag in a full private horde.
248	 */
249	function partyCapScale(state: GameState): number {
250	  return Math.max(1, Math.ceil(state.players.size / 2));
251	}
252	
253	/** Trickles hostile mobs in around the player at night, up to the cap. Difficulty scales the cadence and cap; Peaceful spawns none. */
254	export function tickHostileSpawnDirector(state: GameState, dt: number, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
255	  if (!hostilesSpawn(state.difficulty)) return;
256	  state.timers.hostileSpawnTimer += dt;
257	  const interval = HOSTILE_SPAWN_INTERVAL_SECONDS * hostileSpawnIntervalScale(state.difficulty);
258	  if (state.daylight >= HOSTILE_SPAWN_BELOW_DAYLIGHT || state.timers.hostileSpawnTimer < interval) return;
259	  state.timers.hostileSpawnTimer = 0;
260	
261	  const cap = Math.round(HOSTILE_CAP * hostileCapScale(state.difficulty)) * partyCapScale(state);
262	  const livingHostiles = state.mobs.filter((mob) => mob.hostile).length;
263	  if (livingHostiles >= cap) return;
264	
265	  const center = spawnCenterPlayer(state, rng);
266	  if (!center) return;
267	  const spawnKinds: Array<"zombie" | "skeleton" | "spider" | "creeper"> = ["zombie", "skeleton", "spider", "creeper"];
268	  const kind = spawnKinds[Math.floor(rng() * spawnKinds.length)];
269	  // A wave is 1–2 mobs, but never more than the slots left under the cap — so a
270	  // 2-pack rolled at cap-1 can't overshoot (especially Easy's tighter cap of 8).
271	  spawnMobGroup(
272	    state,
273	    {
274	      kind,
275	      hostile: true,
276	      count: Math.min(cap - livingHostiles, 1 + (rng() > 0.7 ? 1 : 0)),
277	      centerX: center.position.x,
278	      centerZ: center.position.z,
279	      radius: Math.max(26, RENDER_RADIUS * 0.85),
280	      minRadius: HOSTILE_SPAWN_MIN_RADIUS
281	    },
282	    rng,
283	    surfaceYAt
284	  );
285	}
286	
287	const SPAWNER_KINDS: ReadonlyArray<"zombie" | "skeleton" | "spider"> = ["zombie", "skeleton", "spider"];
288	
