/**
 * Extra light absorbed when light enters this block, on top of the 1-per-step
 * cost of horizontal/diagonal spread. 0 = fully transparent (air, glass), small
 * values attenuate (water, leaves), OPAQUE fully blocks. New blocks default to
 * OPAQUE — a solid block casts shadow until classified otherwise.
 */
export function opacity(block: BlockId): number {
  // Redstone overlays (wire, lever, button, plate, torch) are tiny shapes far
  // from filling their cell — they must not black it out. The lamp is a full
  // cube and stays default-opaque (an opaque emitter, like lava). Rails are
  // the same flat-overlay shape.
  if (isRedstoneOverlay(block) || isRailBlock(block)) return 0;
  switch (block) {
    case BlockId.Air:
    case BlockId.Glass:
      return 0;
    case BlockId.Leaves:
    case BlockId.Water:
    case BlockId.Kelp:
      return 1;
    default:
      return OPAQUE;
  }
}

/** True if the block stops light entirely (cannot be lit, cannot transmit). */
export function isLightBlocker(block: BlockId): boolean {
  return opacity(block) >= OPAQUE;
}

/**
 * Block light a source block emits (0 = not a light source). Torch and lava are
 * added with their blocks in later commits; the default keeps every other block
 * dark.
 */
export function emission(block: BlockId): number {
  switch (block) {
    case BlockId.Torch:
      return 14;
    case BlockId.Lava:
      return MAX_LIGHT;
    // A lit redstone torch glows dimmer than a real torch; the powered lamp is
    // a full-strength light source. Their off variants emit nothing — a power
    // toggle swaps the id, and applyEdit re-derives emission at the cell.
    case BlockId.RedstoneTorch:
      return 7;
    case BlockId.RedstoneLampOn:
      return MAX_LIGHT;
    default:
      return 0;
  }
}

