/** Points the player's eye ray at a world position (matches lookDirection's yaw/pitch convention: x = -cp·sin(yaw), y = sin(pitch), z = -cp·cos(yaw)). */
function aimAt(player: PlayerState, tx: number, ty: number, tz: number): void {
