49	  if (world.get(x, baseY - 1, z) !== BlockId.Obsidian) return null;
50	
51	  // Slide to the interior's min corner along the axis (bounded by the max width).
52	  let bx = x;
53	  let bz = z;
54	  for (let guard = 0; guard < PORTAL_MAX_INTERIOR.w - 1 && isInteriorCell(world.get(bx - dx, baseY, bz - dz)); guard += 1) {
55	    bx -= dx;
56	    bz -= dz;
57	  }
58	
59	  // Measure the interior rectangle from the base corner.
60	  let w = 0;
61	  while (w < PORTAL_MAX_INTERIOR.w && isInteriorCell(world.get(bx + dx * w, baseY, bz + dz * w))) w += 1;
62	  let h = 0;
63	  while (h < PORTAL_MAX_INTERIOR.h && isInteriorCell(world.get(bx, baseY + h, bz))) h += 1;
64	  if (w < PORTAL_MIN_INTERIOR.w || h < PORTAL_MIN_INTERIOR.h) return null;
65	
66	  // Every interior cell must be open…
67	  for (let i = 0; i < w; i += 1) {
68	    for (let j = 0; j < h; j += 1) {
69	      if (!isInteriorCell(world.get(bx + dx * i, baseY + j, bz + dz * i))) return null;
70	    }
71	  }
72	  // …inside a full obsidian border. Corners ride the top/bottom rows (i = -1
73	  // and i = w); an oversize interior also fails here (the cell past the max
74	  // width/height would have to be obsidian, but it read as interior above).
75	  for (let i = -1; i <= w; i += 1) {
76	    if (world.get(bx + dx * i, baseY - 1, bz + dz * i) !== BlockId.Obsidian) return null;
77	    if (world.get(bx + dx * i, baseY + h, bz + dz * i) !== BlockId.Obsidian) return null;
78	  }
79	  for (let j = 0; j < h; j += 1) {
80	    if (world.get(bx - dx, baseY + j, bz - dz) !== BlockId.Obsidian) return null;
81	    if (world.get(bx + dx * w, baseY + j, bz + dz * w) !== BlockId.Obsidian) return null;
82	  }
83	  return { axis, base: { x: bx, y: baseY, z: bz }, w, h };
84	}
