86	/** Fills a validated frame's interior with the portal surface (each cell rides the block diff + relight). */
87	export function fillPortalFrame(state: GameState, frame: PortalFrame): void {
88	  const dx = frame.axis === "x" ? 1 : 0;
89	  const dz = frame.axis === "z" ? 1 : 0;
90	  for (let i = 0; i < frame.w; i += 1) {
91	    for (let j = 0; j < frame.h; j += 1) {
92	      state.blockChanges.set(frame.base.x + dx * i, frame.base.y + j, frame.base.z + dz * i, BlockId.NetherPortal);
93	    }
94	  }
95	  state.worldMeshDirty = true;
96	}
