99	 * Right-click use of flint & steel on an obsidian block: the cell in front of
100	 * the struck face is the interior candidate. A valid frame lights (fills with
101	 * the portal surface, wears the striker by one) — unless portals are disabled
102	 * (an online world), which denies with its own reason so the shell can explain.
103	 * Returns true when the click is consumed, even on a refusal.
104	 */
105	export function tryIgnitePortal(state: GameState, player: PlayerState, emit: EmitGameEvent, allowed: boolean, rng: () => number): boolean {
106	  const slot = player.inventory[player.selectedSlot];
107	  if (slot?.id !== "flint_and_steel" || slot.count <= 0) return false;
108	  scratchEye.set(player.position.x, player.position.y + EYE_HEIGHT, player.position.z);
109	  lookDirection(player.yaw, player.pitch, scratchDir);
110	  const result = voxelRaycast(state.world, scratchEye, scratchDir, MINE_REACH);
111	  if (!result) return false;
112	  if (state.world.get(result.hit.x, result.hit.y, result.hit.z) !== BlockId.Obsidian) return false;
113	
114	  const frame = findPortalFrame(state.world, result.previous.x, result.previous.y, result.previous.z);
115	  if (!frame) {
116	    emit({ type: "portalDenied", reason: "invalidFrame" });
117	    return true;
118	  }
119	  if (!allowed) {
120	    emit({ type: "portalDenied", reason: "online" });
121	    return true;
122	  }
123	  fillPortalFrame(state, frame);
124	  player.inventory = consumeToolDurability(player.inventory, player.selectedSlot, 1, rng) ?? player.inventory;
125	  emit({ type: "portalLit" });
126	  return true;
127	}
