155	    const key = state.world.index(cx, cy, cz);
156	    if (visited.has(key)) continue;
157	    visited.add(key);
158	    if (state.world.get(cx, cy, cz) !== BlockId.NetherPortal) continue;
159	    state.blockChanges.set(cx, cy, cz, BlockId.Air);
160	    cleared += 1;
161	    stack.push([cx + 1, cy, cz], [cx - 1, cy, cz], [cx, cy + 1, cz], [cx, cy - 1, cz], [cx, cy, cz + 1], [cx, cy, cz - 1]);
162	  }
163	  state.worldMeshDirty = true;
164	}
