31	export type CreateRendererResult = { ok: true; renderer: GameRenderer } | { ok: false; error: string };
32	
33	// Caves keep this faint floor of visibility instead of going pure black, and
34	// block light is emitted with this warm tint.
35	const SKY_LIGHT_FLOOR = 0.05;
36	const TORCH_TINT = "vec3(1.35, 1.06, 0.62)";
37	
38	/**
39	 * Add per-voxel darkness to a lit world material via the baked aLight attribute
40	 * (skyExposure, blockLight). The scene's sun + hemisphere already scale with
41	 * daylight, so day/night needs no extra uniform and no re-mesh: this patch gates
42	 * the scene-lit color by sky exposure — caves go dark while the surface stays
43	 * lit and dims at night with the scene lights — then adds block light back as an
44	 * albedo-tinted glow that survives the gate, so a torch lights a pitch-black
45	 * cave. Anchored on stable ShaderChunk includes; the e2e triangle check guards
46	 * against a future Three.js bump breaking the string replace.
47	 */
48	function patchVoxelLighting(material: THREE.MeshStandardMaterial): void {
49	  material.onBeforeCompile = (shader) => {
50	    shader.vertexShader = "attribute vec2 aLight;\nvarying vec2 vLight;\n" + shader.vertexShader.replace("void main() {", "void main() {\n  vLight = aLight;");
51	    shader.fragmentShader =
52	      "varying vec2 vLight;\n" +
53	      shader.fragmentShader
54	        .replace("#include <color_fragment>", "#include <color_fragment>\n  vec3 mcAlbedo = diffuseColor.rgb;")
55	        .replace(
56	          "#include <opaque_fragment>",
57	          `#include <opaque_fragment>\n  gl_FragColor.rgb = gl_FragColor.rgb * max(vLight.x, ${SKY_LIGHT_FLOOR.toFixed(3)}) + mcAlbedo * vLight.y * ${TORCH_TINT};`
58	        );
59	  };
60	}
61	
62	/**
63	 * Maps simulation state to Three.js every frame in sync(): camera from
64	 * yaw/pitch, world mesh from the voxel data (region-windowed, rebuilt when the
65	 * player crosses a RENDER_GRID boundary or state.worldMeshDirty is set), mob
66	 * models keyed by mob id, the held item, the crack overlay, and day-night
67	 * lighting. Owns every GPU resource and frees them in dispose().
68	 */
69	export class GameRenderer {
70	  private readonly mount: HTMLElement;
71	  private readonly scene: THREE.Scene;
72	  private readonly camera: THREE.PerspectiveCamera;
73	  private readonly webgl: THREE.WebGLRenderer;
74	  private readonly sun: THREE.DirectionalLight;
