81	  // Solid + glass terrain share one block atlas; held as a field so dispose() can
82	  // release it (THREE.Material.dispose() does not dispose its map texture).
83	  private readonly blockAtlasTexture: THREE.Texture;
84	  private worldMesh: THREE.Mesh;
85	  private glassMesh: THREE.Mesh;
