100	  /** Names/skins for remote avatars (a NetworkSession provides it; SP renders none). */
101	  remotePlayerInfo: (id: string) => RemotePlayerInfo = () => ({ name: "player", skinId: null });
102	  private readonly particles: ParticleSystem;
