111	  /** WebGL context creation can fail (blocked, unsupported) — surface it instead of throwing. */
112	  static create(mount: HTMLElement): CreateRendererResult {
113	    try {
114	      return { ok: true, renderer: new GameRenderer(mount) };
115	    } catch (error) {
116	      return { ok: false, error: error instanceof Error ? error.message : "Failed to initialize WebGL renderer" };
117	    }
