    for (let j = 0; j < 3; j += 1) {
      bc.set(px - 1, py + j, pz, 90);
      bc.set(px + 2, py + j, pz, 90);
    }
    for (let i = 0; i < 2; i += 1) {
      for (let j = 0; j < 3; j += 1) bc.set(px + i, py + j, pz, 91);
