1	import { BURIED_TREASURE_LOOT } from "@/lib/game/buriedTreasureLoot";
2	import { DUNGEON_LOOT } from "@/lib/game/dungeonLoot";
3	import { FISHING_LOOT } from "@/lib/game/fishingLoot";
4	import { SHIPWRECK_LOOT } from "@/lib/game/shipwreckLoot";
5	import { BLOCK_TO_SLOT, ITEM_DEF_BY_ID } from "@/lib/game/items";
6	import { MOB_DROPS } from "@/lib/game/mobLoot";
7	import { RECIPES } from "@/lib/game/recipes";
8	import type { MobKind, Recipe } from "@/lib/game/types";
9	
10	/**
11	 * "How to obtain" hints for the recipe book: when a recipe is short an
12	 * ingredient, the tooltip tells the player where that item comes from. Hints are
13	 * derived once from the existing static loot/recipe tables — no new data — so a
14	 * new item or recipe is covered automatically (special block drops aside).
15	 */
16	
17	/** Verb for a craftable item, keyed by the station its recipe needs ("none" = plain crafting). */
18	const CRAFT_VERB: Record<"none" | NonNullable<Recipe["station"]>, string> = {
19	  none: "Craft it",
20	  furnace: "Smelt it",
21	  villager: "Trade for it",
22	  brewing: "Brew it"
23	};
24	
25	/** Display names for mobs, used in "Hunt <mob>" hints. */
26	const MOB_LABELS: Record<MobKind, string> = {
27	  sheep: "a sheep",
28	  chicken: "a chicken",
29	  horse: "a horse",
30	  cow: "a cow",
31	  pig: "a pig",
32	  wolf: "a wolf",
33	  cat: "a cat",
34	  cod: "a cod",
35	  salmon: "a salmon",
36	  drowned: "a drowned",
37	  zombie: "a zombie",
38	  skeleton: "a skeleton",
39	  spider: "a spider",
40	  creeper: "a creeper",
41	  raider: "a raider",
42	  villager: "a villager",
43	  boss: "the boss",
44	  imp: "an imp",
45	  scorcher: "a scorcher"
46	};
47	
48	/**
49	 * Overrides for items whose dropped form differs from the block you break, so the
50	 * generic "Mine <item label>" reads correctly (coal comes from coal ore;
51	 * saplings/seeds/wheat are chance drops handled in `rollBlockDrops`, not direct).
52	 */
53	const MINE_OVERRIDES: Record<string, string> = {
54	  coal: "Mine coal ore",
55	  sapling: "Break leaves",
56	  seeds: "Break grass",
57	  wheat: "Harvest grown wheat"
58	};
59	
60	const labelFor = (itemId: string): string => ITEM_DEF_BY_ID[itemId]?.label ?? itemId;
61	
62	/**
63	 * itemId → single best "how to obtain" hint, precomputed once from the static
64	 * tables. Priority is chosen so each item points at its most natural, repeatable
65	 * source: hunt a common mob (not the one-off boss) → craft → mine → shipwreck →
66	 * fish → dungeon/buried chest → boss. Hunting comes before crafting so a raw drop like wool says "hunt a
67	 * sheep" rather than the obscure craft-from-string path; the boss is last so its
68	 * drops (e.g. diamond ore) prefer mining and only surface the boss for its
69	 * trophy. The first source set for an item wins.
70	 */
71	const SOURCE_HINTS: Map<string, string> = (() => {
72	  const hints = new Map<string, string>();
73	  const set = (itemId: string, hint: string): void => {
74	    if (!hints.has(itemId)) hints.set(itemId, hint);
75	  };
76	
77	  // 1. Hunt (every mob except the boss — it isn't a farmable source). Entries
78	  // behind a `chance` gate are lucky extras, not the item's natural source
79	  // (the drowned's rare spear shouldn't beat "Craft it"), so they don't hint.
80	  for (const [kind, drops] of Object.entries(MOB_DROPS)) {
81	    if (kind === "boss") continue;
82	    for (const drop of drops) {
83	      if (drop.chance !== undefined) continue;
84	      set(drop.itemId, `Hunt ${MOB_LABELS[kind as MobKind]}`);
85	    }
86	  }
87	  // 2. Craft (incl. smelt/trade/brew). The first recipe producing the item wins.
88	  for (const recipe of RECIPES) set(recipe.result.slotId, CRAFT_VERB[recipe.station ?? "none"]);
89	  // 2b. Fluids: filled buckets come from using an empty bucket on the world.
90	  set("water_bucket", "Scoop up water with a bucket");
91	  set("lava_bucket", "Scoop up lava with a bucket");
92	  // 3. Mine (direct block drops, then chance-drop overrides not in BLOCK_TO_SLOT).
93	  for (const itemId of Object.values(BLOCK_TO_SLOT)) {
94	    if (itemId) set(itemId, MINE_OVERRIDES[itemId] ?? `Mine ${labelFor(itemId)}`);
95	  }
96	  for (const [itemId, hint] of Object.entries(MINE_OVERRIDES)) set(itemId, hint);
97	  // 4. Shipwreck chests — before fishing, so the treasure map (also a rare
98	  // catch) points at its main, repeatable source: diving wrecks.
99	  for (const tier of Object.values(SHIPWRECK_LOOT)) {
100	    for (const entry of tier) set(entry.itemId, "Find it in a shipwreck");
101	  }
102	  // 5. Fish.
103	  for (const entry of FISHING_LOOT) set(entry.itemId, "Catch it while fishing");
104	  // 6. Dungeon and buried-treasure chests.
105	  for (const tier of Object.values(DUNGEON_LOOT)) {
106	    for (const entry of tier) set(entry.itemId, "Find it in a dungeon chest");
107	  }
108	  for (const tier of Object.values(BURIED_TREASURE_LOOT)) {
109	    for (const entry of tier) set(entry.itemId, "Dig up buried treasure");
110	  }
111	  // 7. Boss (last resort — only its trophy drops with no other source reach here).
112	  for (const drop of MOB_DROPS.boss) set(drop.itemId, "Defeat the boss");
113	  return hints;
114	})();
115	
116	/** A short, human "how to obtain" hint for an item, or null when its source is unknown. */
117	export function itemSourceHint(itemId: string): string | null {
118	  return SOURCE_HINTS.get(itemId) ?? null;
119	}

